// Common PolyBench-style definitions (DATA_TYPE, N, etc.)
#include "defines.hpp"
#include "cholesky.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// -----------------------------------------------------------------------------
// Initialize the matrix A as in the original PolyBench cholesky.c
//   1) Build a lower-triangular matrix A0:
//        for i in [0..n-1]:
//          for j in [0..i]:
//              A0[i][j] = (DATA_TYPE)(-j % n) / n + 1
//          for j in [i+1..n-1]:
//              A0[i][j] = 0
//          A0[i][i] = 1
//   2) Form A := A0 * A0^T  (positive semi-definite).
//
// We store matrices in Halide::Buffer as A(x, y) = A[row = y][col = x],
// i.e. first dimension is the column index, second is the row index,
// matching the gemm.cpp example style.
// -----------------------------------------------------------------------------
static void init_array(int n, Halide::Buffer<num_t, 2> A) {
    Var x("x"), y("y");  // x = column index j, y = row index i
    Func A0("A0"), B("B");

    // Step 1: build the initial lower-triangular matrix A0(x, y).
    //
    // In C:
    //   for (i = 0; i < n; i++) {
    //     for (j = 0; j <= i; j++)
    //       A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
    //     for (j = i+1; j < n; j++)
    //       A[i][j] = 0;
    //     A[i][i] = 1;
    //   }
    //
    // Here: i -> y, j -> x, and A[i][j] -> A0(x, y).
    Expr minus_mod = -(x % n);  // (-j % n) for j = x
    Expr base_val =
        cast<num_t>(minus_mod) / cast<num_t>(n) + cast<num_t>(1);

    // For x < y: use base_val; for x == y: override to 1; for x > y: 0.
    A0(x, y) = select(
        x < y, base_val,
        select(x == y, cast<num_t>(1), cast<num_t>(0)));

    // Step 2: A := A0 * A0^T
    //
    // In C:
    //   B[r][s] = sum_t A[r][t] * A[s][t];
    //   A[r][s] = B[r][s];
    //
    // With our mapping:
    //   row r -> y, col s -> x
    //   A[r][t] -> A0(t, r) = A0(t, y)
    //   A[s][t] -> A0(t, s) = A0(t, x)
    //
    // So B(x, y) = sum_{k=0}^{n-1} A0(k, y) * A0(k, x).
    RDom k(0, n, "k");
    B(x, y) = cast<num_t>(0);
    B(x, y) += A0(k, y) * A0(k, x);

    // Realize B directly into the provided buffer A.
    B.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // A is N x N. We store as A(x, y) = A[row = y][col = x].
    Halide::Buffer<num_t, 2> A(n, n);

    // Initialize A to a positive semi-definite matrix as in the C code.
    init_array(n, A);

    // -------------------------------------------------------------------------
    // Halide description of the inner dot-products used by Cholesky.
    //
    // Original kernel (C):
    //
    //   for (i = 0; i < N; i++) {
    //     // j < i
    //     for (j = 0; j < i; j++) {
    //       for (k = 0; k < j; k++) {
    //         A[i][j] -= A[i][k] * A[j][k];
    //       }
    //       A[i][j] /= A[j][j];
    //     }
    //     // i == j case
    //     for (k = 0; k < i; k++) {
    //       A[i][i] -= A[i][k] * A[i][k];
    //     }
    //     A[i][i] = SQRT_FUN(A[i][i]);
    //   }
    //
    // We express the reduction pieces (the sums over k) in Halide,
    // and keep the outer i,j loops and scalar updates in C++, using
    // double-buffering-on-host semantics as recommended for DP codes.
    // -------------------------------------------------------------------------

    // ImageParam representing the current state of A.
    // Dimensions: (x = column, y = row).
    ImageParam A_param(type_of<num_t>(), 2, "A_param");

    // Scalar parameters for the current indices i and j.
    Param<int> i_param("i_param");
    Param<int> j_param("j_param");

    // Dot product for the off-diagonal update: sum_{k=0..j-1} A[i][k]*A[j][k]
    //
    // Mapping to Buffer:
    //   A[i][k] -> A_param(k, i)
    //   A[j][k] -> A_param(k, j)
    //
    // Result is a scalar (0-D Func).
    Func dot_lower("dot_lower");
    RDom k_lower(0, j_param, "k_lower");
    dot_lower() = cast<num_t>(0);
    dot_lower() += A_param(k_lower, i_param) * A_param(k_lower, j_param);

    // Dot product for the diagonal update: sum_{k=0..i-1} A[i][k]*A[i][k]
    //
    // Mapping:
    //   A[i][k] -> A_param(k, i)
    Func dot_diag("dot_diag");
    RDom k_diag(0, i_param, "k_diag");
    dot_diag() = cast<num_t>(0);
    dot_diag() += A_param(k_diag, i_param) * A_param(k_diag, i_param);

    // Compile the reduction pipelines ahead of timing.
    dot_lower.compile_jit();
    dot_diag.compile_jit();

    // Bind the ImageParam to the initial buffer.
    A_param.set(A);

    // -------------------------------------------------------------------------
    // Run the Cholesky factorization, timing only the main kernel.
    // -------------------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    for (int i = 0; i < n; i++) {
        // Off-diagonal entries A[i][j] for j < i.
        for (int j = 0; j < i; j++) {
            // Set the current indices for the reduction.
            i_param.set(i);
            j_param.set(j);

            // Compute s = sum_{k=0..j-1} A[i][k] * A[j][k] via Halide.
            Halide::Buffer<num_t> s_buf = dot_lower.realize();
            num_t s = s_buf();

            // Map A[i][j] -> A(j, i) and A[j][j] -> A(j, j)
            num_t a_ij = A(j, i);
            num_t a_jj = A(j, j);

            // A[i][j] -= s; A[i][j] /= A[j][j];
            a_ij = (a_ij - s) / a_jj;
            A(j, i) = a_ij;
        }

        // Diagonal entry A[i][i]:
        //   A[i][i] -= sum_{k=0..i-1} A[i][k]*A[i][k];
        //   A[i][i] = sqrt(A[i][i]);
        i_param.set(i);
        Halide::Buffer<num_t> sdiag_buf = dot_diag.realize();
        num_t sdiag = sdiag_buf();

        num_t a_ii = A(i, i);
        a_ii = a_ii - sdiag;
        a_ii = std::sqrt(a_ii);
        A(i, i) = a_ii;
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // -------------------------------------------------------------------------
    // Optional: print the resulting lower-triangular factor, similar
    // to the original PolyBench print_array (only j <= i entries).
    // -------------------------------------------------------------------------
    if (argc > 1) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j <= i; j++) {
                // A[i][j] -> A(j, i)
                std::cerr << A(j, i) << '\n';
            }
        }
    }

    // Print timing in seconds.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
