#include <chrono>
#include <cmath>
#include <iomanip>
#include <iostream>

#include "Halide.h"

// Common PolyBench-style definitions (problem sizes, DATA_TYPE, etc).
// These should define N and DATA_TYPE, analogous to the C version.
#include "defines.hpp"
#include "cholesky.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// -----------------------------------------------------------------------------
// Initialize the matrix A to be symmetric positive semi-definite, matching the
// semantics of the PolyBench init_array() in cholesky.c.
// -----------------------------------------------------------------------------
static void init_array(int n, Halide::Buffer<num_t, 2> A) {
    // A is logically A[i][j] in C, but we store it as A(j, i) in Halide
    // (first dimension is column, second is row), following the gemm.cpp pattern.

    Var j("j"), i("i");
    Func A0("A0"), B("B");

    // Construct the initial lower-triangular matrix A0, equivalent to:
    // for (i = 0; i < n; i++) {
    //   for (j = 0; j <= i; j++)
    //     A[i][j] = (-j % n) / n + 1;  // with integer arithmetic
    //   for (j = i+1; j < n; j++)
    //     A[i][j] = 0;
    //   A[i][i] = 1;
    // }
    //
    // Since 0 <= j < n, (-j % n) == -j in C, so (-j % n)/n + 1 == 1 - j/n.
    Expr n_expr = cast<num_t>(n);
    Expr j_f    = cast<num_t>(j);

    // A0(j, i) corresponds to A[i][j]
    A0(j, i) = select(j == i,
                      cast<num_t>(1),
                      select(j <= i,
                             cast<num_t>(1) - j_f / n_expr,
                             cast<num_t>(0)));

    // Now form B = A0 * A0^T, i.e.
    // B[r][s] = sum_t A[r][t] * A[s][t];
    // and finally copy B back into A.
    //
    // In Buffer / Func coordinates:
    //   A0(j, i) = A[i][j]
    //   B(j, i)  = B[i][j]
    //
    // B(i_row, j_col) = sum_t A[i_row][t] * A[j_col][t]
    //                 = sum_t A0(t, i_row) * A0(t, j_col)
    RDom t(0, n, "t");

    B(j, i) = cast<num_t>(0);
    B(j, i) += A0(t, i) * A0(t, j);

    // Optionally schedule:
    A0.compute_root();
    B.compute_root();

    // Realize B into A. A has shape (n, n): x = j, y = i.
    B.realize(A);
}

// -----------------------------------------------------------------------------
// Halide-assisted Cholesky factorization.
// We keep the outer (i, j) loops on the host to preserve the sequential
// dependencies, and use Halide only for the inner reductions over k.
// This matches the original kernel_cholesky semantics.
// -----------------------------------------------------------------------------
static void kernel_cholesky(int n, Halide::Buffer<num_t, 2> &A) {
    // A(j, i) corresponds to C's A[i][j].

    // ImageParam to expose the current matrix A to Halide.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");

    // Params for the current (i, j) / i index used in the reductions.
    Param<int> i_param("i_param");
    Param<int> j_param("j_param");
    Param<int> i_diag_param("i_diag_param");

    // ------------------------------
    // Off-diagonal reduction:
    //
    // sum_off(i, j) = sum_{k=0}^{j-1} A[i][k] * A[j][k]
    //
    // In Buffer coordinates:
    //   A[i][k] -> A(k, i)
    //   A[j][k] -> A(k, j)
    // ------------------------------
    RDom r_off(0, j_param, "r_off");
    Func sum_off("sum_off");
    sum_off() = cast<num_t>(0);
    sum_off() += A_param(r_off, i_param) * A_param(r_off, j_param);

    // ------------------------------
    // Diagonal reduction:
    //
    // sum_diag(i) = sum_{k=0}^{i-1} A[i][k]^2
    //
    // In Buffer coordinates:
    //   A[i][k] -> A(k, i)
    // ------------------------------
    RDom r_diag(0, i_diag_param, "r_diag");
    Func sum_diag("sum_diag");
    sum_diag() = cast<num_t>(0);
    sum_diag() += A_param(r_diag, i_diag_param) *
                  A_param(r_diag, i_diag_param);

    // JIT-compile the small reduction pipelines once.
    sum_off.compile_jit();
    sum_diag.compile_jit();

    // Host-driven Cholesky loop nest:
    //
    // for (i = 0; i < n; i++) {
    //   // j < i
    //   for (j = 0; j < i; j++) {
    //     for (k = 0; k < j; k++)
    //        A[i][j] -= A[i][k] * A[j][k];
    //     A[i][j] /= A[j][j];
    //   }
    //   // i == j
    //   for (k = 0; k < i; k++)
    //     A[i][i] -= A[i][k] * A[i][k];
    //   A[i][i] = sqrt(A[i][i]);
    // }
    //
    // We express the k-loops via Halide reductions, and perform the
    // scalar updates on A directly on the host.

    for (int i = 0; i < n; ++i) {
        // Process off-diagonal entries in row i: j < i
        for (int j = 0; j < i; ++j) {
            // Bind current matrix and loop indices for the reduction.
            A_param.set(A);
            i_param.set(i);
            j_param.set(j);

            // Compute sum_{k=0}^{j-1} A[i][k] * A[j][k].
            Halide::Buffer<num_t> sum_buf = sum_off.realize();
            num_t sum = sum_buf();

            num_t aij = A(j, i);  // A[i][j]
            num_t ajj = A(j, j);  // A[j][j]
            aij = (aij - sum) / ajj;
            A(j, i) = aij;
        }

        // Process diagonal entry A[i][i].
        A_param.set(A);
        i_diag_param.set(i);

        // Compute sum_{k=0}^{i-1} A[i][k]^2.
        Halide::Buffer<num_t> sumd_buf = sum_diag.realize();
        num_t sumd = sumd_buf();

        num_t aii = A(i, i);  // A[i][i]
        aii = aii - sumd;
        aii = static_cast<num_t>(std::sqrt(static_cast<double>(aii)));
        A(i, i) = aii;
    }
}

// -----------------------------------------------------------------------------
// Main
// -----------------------------------------------------------------------------
int main(int argc, char *argv[]) {
    // Problem size.
    int n = N;

    // Matrix A: stored as A(j, i), with shape (n, n).
    Halide::Buffer<num_t, 2> A(n, n);

    // Initialize A to a symmetric positive semi-definite matrix.
    init_array(n, A);

    // Time the Cholesky factorization.
    auto start = std::chrono::high_resolution_clock::now();

    kernel_cholesky(n, A);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the resulting lower-triangular factor to stderr
    // (only j <= i elements), roughly mirroring PolyBench's print_array.
    if (argc > 1) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j <= i; ++j) {
                std::cerr << A(j, i) << '\n';
            }
        }
    }

    // Print elapsed time in seconds to stdout.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
