    Expr neg_mod = cast<num_t>(((-j) % n));
    Expr lower_val = neg_mod / cast<num_t>(n) + cast<num_t>(1);

    // j < i  : lower triangular formula
    // j == i : diagonal set to 1
    // j > i  : upper triangular set to 0
    A_init(j, i) = select(j < i,
