    Var r("r"), s("s");
    RDom t(0, n, "t");

    Func B_init("B_init");
    B_init(s, r) = cast<num_t>(0);
    B_init(s, r) += A_param(t, r) * A_param(t, s);

    B_init.realize(B);

    // Copy B back into A
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    B_param.set(B);

    Func A_copy("A_copy");
    A_copy(j, i) = B_param(j, i);
    A_copy.realize(A);
}

/*
 * Main computational kernel.
 * Translation of kernel_cholesky() to C++ using Halide::Buffer
 * instead of raw C arrays. This is inherently sequential (DP-like)
 * and is kept as explicit loops over the buffer.
 *
 * Original C:
 *
 * for (i = 0; i < N; i++) {
 *   // j < i
 *   for (j = 0; j < i; j++) {
 *     for (k = 0; k < j; k++) {
 *       A[i][j] -= A[i][k] * A[j][k];
 *     }
 *     A[i][j] /= A[j][j];
 *   }
 *   // i == j case
 *   for (k = 0; k < i; k++) {
 *     A[i][i] -= A[i][k] * A[i][k];
 *   }
 *   A[i][i] = SQRT_FUN(A[i][i]);
 * }
 */
static void kernel_cholesky[[gnu::flatten, gnu::noinline]](int n,
                                                           Halide::Buffer<num_t, 2> A) {
    for (int i = 0; i < n; i++) {
        // j < i
        for (int j = 0; j < i; j++) {
            for (int k = 0; k < j; k++) {
                // A[i][j] -= A[i][k] * A[j][k];
                A(j, i) -= A(k, i) * A(k, j);
            }
            // A[i][j] /= A[j][j];
            A(j, i) /= A(j, j);
        }

        // i == j case
        for (int k = 0; k < i; k++) {
            // A[i][i] -= A[i][k] * A[i][k];
            A(i, i) -= A(k, i) * A(k, i);
        }

        // A[i][i] = SQRT_FUN(A[i][i]);
        A(i, i) = SQRT_FUN(A(i, i));
    }
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Matrix A: stored as Buffer(x = column j, y = row i)
    Halide::Buffer<num_t, 2> A(n, n);

    // Initialize A using Halide-based initialization
    init_array(n, A);

    // Time the kernel (as PolyBench does)
    auto start = std::chrono::high_resolution_clock::now();

    kernel_cholesky(n, A);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optional printing of the result to prevent dead-code elimination.
    // We mimic the style used in example/gemm.cpp.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j <= i; j++) {
                // A[i][j] -> A(j, i)
                std::cerr << A(j, i) << '\n';
            }
        }
    }

    // Print elapsed time (seconds) with 6 decimal places
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
