#include <iomanip>
#include <iostream>

#include "Halide.h"

// include common definitions (DATA_TYPE, N, etc.)
#include "defines.hpp"

// include benchmark-specific definitions
#include "cholesky.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize matrix A as in the original PolyBench cholesky.c:
 *
 * 1) First build a lower-triangular matrix A with:
 *      for i in 0..n-1:
 *        for j in 0..i:   A[i][j] = (-j % n) / n + 1;
 *        for j in i+1..n-1: A[i][j] = 0;
 *        A[i][i] = 1;
 *
 *    Note: A is N x N, stored row-major in C as A[i][j].
 *
 * 2) Then make it symmetric positive semi-definite via:
 *      B[r][s] = sum_t A[r][t] * A[s][t];
 *      A[r][s] = B[r][s];
 *
 * We represent C arrays A[i][j] as Halide::Buffer<num_t, 2> with indexing:
 *   A_buf(x, y) == A[y][x]
 * so x corresponds to the column index j, y to the row index i.
 */
static void init_array(int n, Halide::Buffer<num_t, 2> A) {
    Var x("x"), y("y");
    Func A_init("A_init"), B("B");

    // n as a Halide Expr
    Expr n_expr = n;
    Expr j = x;  // column index j corresponds to x

    // Base expression for lower-triangular part: (-j % n) / n + 1
    Expr base =
        cast<num_t>(((-j) % n_expr)) / cast<num_t>(n_expr) + cast<num_t>(1);

    // First build the lower-triangular, unit-diagonal A_init:
    //
    // If j < i   (x < y):  A[i][j] = base
    // If j > i   (x > y):  A[i][j] = 0
    // If j == i  (x == y): A[i][i] = 1
    A_init(x, y) = select(x < y,
                          base,
                          x > y,
                          cast<num_t>(0),
                          cast<num_t>(1));

    // Now build B = A * A^T:
    //
    // B[r][s] = sum_t A[r][t] * A[s][t]
    //
    // In Buffer form:
    //   A[r][t] == A_init(t, r)
    //   A[s][t] == A_init(t, s)
    //   B[r][s] == B_buf(s, r)
    //
    // So we define:
    //   B(x, y) (== B_buf(x, y) == B[y][x]) =
    //       sum_t A_init(t, y) * A_init(t, x)
    RDom t(0, n_expr, "t");
    B(x, y) = cast<num_t>(0);
    B(x, y) += A_init(t, y) * A_init(t, x);

    // Realize B directly into A's storage. After this, A_buf(x, y) holds
    // B[y][x], i.e., A[r][s] = B[r][s] as in the original C code.
    B.realize(A);
}

/**
 * Cholesky factorization kernel.
 *
 * Original C code (row-major A[i][j]):
 *
 *   for (i = 0; i < n; i++) {
 *     // j < i
 *     for (j = 0; j < i; j++) {
 *       for (k = 0; k < j; k++) {
 *         A[i][j] -= A[i][k] * A[j][k];
 *       }
 *       A[i][j] /= A[j][j];
 *     }
 *     // i == j case
 *     for (k = 0; k < i; k++) {
 *       A[i][i] -= A[i][k] * A[i][k];
 *     }
 *     A[i][i] = SQRT_FUN(A[i][i]);
 *   }
 *
 * This algorithm has loop-carried dependencies along i and j and
 * updates A in-place. Such dynamic programming style cannot be expressed
 * as a single pure Halide Func without illegal self-references, so we
 * implement it as host-side loops operating on a Halide::Buffer.
 *
 * We keep the same update order and semantics.
 */
static void kernel_cholesky(int n, Halide::Buffer<num_t, 2> A) {
    // A is laid out as A(y, x) == A[i][j] from the C version.

    for (int i = 0; i < n; i++) {
        // j < i
        for (int j = 0; j < i; j++) {
            num_t sum = static_cast<num_t>(0);
            for (int k = 0; k < j; k++) {
                // A[i][k] == A(k, i)
                // A[j][k] == A(k, j)
                sum += A(k, i) * A(k, j);
            }

            // A[i][j] -= sum
            // A[i][j] /= A[j][j]
            num_t a_ij = A(j, i);      // A[i][j]
            num_t a_jj = A(j, j);      // A[j][j]
            a_ij = (a_ij - sum) / a_jj;
            A(j, i) = a_ij;
        }

        // i == j case
        num_t sum_diag = static_cast<num_t>(0);
        for (int k = 0; k < i; k++) {
            // A[i][k] == A(k, i)
            num_t a_ik = A(k, i);
            sum_diag += a_ik * a_ik;
        }

        // A[i][i] -= sum_diag; then sqrt
        num_t a_ii = A(i, i);
        a_ii = a_ii - sum_diag;
        a_ii = static_cast<num_t>(std::sqrt(static_cast<double>(a_ii)));
        A(i, i) = a_ii;
    }
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Allocate A as an n x n buffer.
    // Remember: A(x, y) corresponds to C's A[y][x].
    Halide::Buffer<num_t, 2> A(n, n);

    // Initialize data using a Halide pipeline for the SPD construction.
    init_array(n, A);

    // Measure execution time of the Cholesky kernel.
    auto start = std::chrono::high_resolution_clock::now();

    kernel_cholesky(n, A);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the resulting lower-triangular factor.
    // We mirror the idea of PolyBench's print_array, but write to stderr.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j <= i; j++) {
                // A[i][j] == A(j, i)
                std::cerr << A(j, i) << '\n';
            }
        }
    }

    // Print timing in seconds with 6 decimal places, as in the GEMM example.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
